//! Inert LEGEND imports preserve actual owner, attributes and independent descendants.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=group><legend id=source align=initial>Legend<span> child</span></legend><input id=neighbor value=seed></fieldset></form><template id=parked><legend align=parked>Parked</legend></template></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://legend-import.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn legend_inert_import_native_shallow_has_destination_owner_and_no_form(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('source'),owner=document.getElementById('owner'),attr=source.getAttributeNode('align'),target=new Document();source.align='A\ud800Z';var copy=target.importNode(source,false);if(!(copy instanceof HTMLLegendElement)||copy===source||copy.ownerDocument!==target||copy.parentNode!==null||copy.firstChild!==null||copy.form!==null||source.form!==owner||copy.align!==source.align||copy.getAttributeNode('align')===attr||copy.getAttributeNode('align').ownerDocument!==target)throw 'actual shallow imported legend';copy.align='independent';if(source.align!=='A\ud800Z'||attr.value!==source.align||document.getElementById('neighbor').value!=='seed')throw 'independent real import';"#);}
#[test]
fn legend_inert_import_pure_inert_deep_preserves_raw_attributes_and_independent_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','p:legend'),child=doc.createTextNode('R\udfffZ'),target=new Document();source.align='A\ud800Z';source.appendChild(child);source.setAttributeNS('urn:other','q:align','foreign');var copy=target.importNode(source,true);if(copy===source||copy.ownerDocument!==target||copy.form!==null||copy.align!==source.align||copy.firstChild===child||copy.firstChild.ownerDocument!==target||copy.firstChild.parentNode!==copy||copy.firstChild.data!=='R\udfffZ'||copy.getAttributeNS('urn:other','align')!=='foreign')throw 'actual deep inert legend import';copy.firstChild.data='changed';copy.align='changed';if(child.data!=='R\udfffZ'||source.align!=='A\ud800Z'||source.ownerDocument!==doc)throw 'independent descendants';"#);}
#[test]
fn legend_inert_import_parked_parsed_source_keeps_template_owner_and_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('parked'),source=host.content.firstChild,owner=source.ownerDocument,target=new Document(),copy=target.importNode(source,true);if(!(copy instanceof HTMLLegendElement)||copy.align!=='parked'||copy.textContent!=='Parked'||copy.ownerDocument!==target||copy.firstChild.ownerDocument!==target||copy.firstChild===source.firstChild||source.parentNode!==host.content||source.ownerDocument!==owner||copy.form!==null)throw 'actual parked imported legend';");}


#[test]
fn legend_inert_import_actual_destination_parent_controls_form_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('source'),target=new Document(),html='http://www.w3.org/1999/xhtml',root=target.createElementNS(html,'div'),owner=target.createElementNS(html,'form'),fieldset=target.createElementNS(html,'fieldset'),holder=target.createElementNS(html,'div'),copy=target.importNode(source,true);target.appendChild(root);root.appendChild(owner);owner.appendChild(fieldset);fieldset.appendChild(copy);if(copy.form!==owner||source.form!==document.getElementById('owner')||copy.ownerDocument!==target)throw 'actual destination fieldset parent';fieldset.appendChild(holder);holder.appendChild(copy);if(copy.form!==null)throw 'direct parent only';fieldset.appendChild(copy);if(copy.form!==owner||source.parentNode!==document.getElementById('group'))throw 'restored independent owner';"#);}
#[test]
fn legend_inert_import_options_reentry_observes_current_attributes_and_children(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('source'),target=new Document(),calls=0,copy=target.importNode(source,{get selfOnly(){calls++;source.align='current';source.firstChild.data='changed';return false;}});if(calls!==1||copy.align!=='current'||copy.firstChild.data!=='changed'||source.align!=='current')throw 'snapshot follows dictionary conversion';var marker={},caught;try{target.importNode(source,{get selfOnly(){source.align='author';throw marker;}});}catch(e){caught=e;}if(caught!==marker||source.align!=='author'||copy.align!=='current')throw 'abrupt dictionary preserves author effects';"#);}
#[test]
fn legend_inert_import_remaining_native_families_and_deep_controls_are_guarded(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),target=new Document(),html='http://www.w3.org/1999/xhtml';for(var tag of ['script','link','img','iframe','frame','object','embed','input','textarea','select','option','button','form','fieldset','audio','video','source','canvas']){var node=doc.createElementNS(html,tag),caught=false;try{target.importNode(node,false);}catch(e){caught=e.name==='NotSupportedError';}if(!caught||node.ownerDocument!==doc||node.parentNode!==null)throw 'remaining native family guard';}var group=doc.createElementNS(html,'optgroup');group.label='group';group.disabled=true;var groupCopy=target.importNode(group,false);if(groupCopy===group||groupCopy.ownerDocument!==target||groupCopy.parentNode!==null||groupCopy.firstChild!==null||groupCopy.label!=='group'||!groupCopy.disabled||groupCopy.getAttributeNode('label')===group.getAttributeNode('label')||group.ownerDocument!==doc)throw 'actual independent passive group copy';var source=doc.createElementNS(html,'legend'),child=doc.createElementNS(html,'input');source.align='source';source.appendChild(child);var copy=target.importNode(source,false);if(copy.firstChild!==null||copy.align!=='source')throw 'shallow omits guarded children';var caught=false;try{target.importNode(source,true);}catch(e){caught=e.name==='NotSupportedError';}if(!caught||source.firstChild!==child||source.ownerDocument!==doc||copy.firstChild!==null)throw 'deep guarded control preserves source';"#);}
#[test]
fn legend_inert_import_saved_child_origin_precedes_dictionary_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('source'),target=new Document(),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.Document.prototype.importNode,calls=0,options={get selfOnly(){calls++;return false;}},copy=method.call(target,source,options);if(copy.ownerDocument!==target||calls!==1)throw 'captured real import';");p.set_location(&crate::navigation::address("https://other-legend-import.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("method.call(target,source,options);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://legend-import.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==1)throw 'origin precedes options';var again=method.call(target,source,options);if(calls!==2||again===copy||again.ownerDocument!==target)throw 'fresh import recovery';");}
#[test]
fn legend_inert_import_focused_native_source_guard_recovers_without_copy(){let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("source")).unwrap();run(&mut d,&mut f,&mut p,"var target=new Document(),source=document.getElementById('source');");d.native_focus.set(Some(n));let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let e=p.runtime.execute("target.importNode(source,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("DOMException"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);d.native_focus.set(None);p.begin_job();run(&mut d,&mut f,&mut p,"var copy=target.importNode(source,true);if(copy.ownerDocument!==target||copy.align!=='initial'||copy.firstChild===source.firstChild)throw 'focused source recovery';");}

#[test]
fn legend_inert_import_resource_refusal_publishes_no_identity_and_recovers(){
 for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('source'),attr=source.getAttributeNode('align'),target=new Document();source.childNodes;source.firstChild.data;");let Value::Host(target)=p.runtime.execute("target;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("target")};let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("source")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let count=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.inert_node_count();p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("target.importNode(source,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);assert_eq!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.inert_node_count(),count);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"var copy=target.importNode(source,true);if(copy.ownerDocument!==target||copy.align!=='initial'||copy.firstChild===source.firstChild||copy.form!==null||source.getAttributeNode('align')!==attr)throw 'fresh import resource recovery';");assert_eq!(d.attr(n,"align"),Some("initial"));}
}
